import { describe, expect, test } from "bun:test";
import { AccountTypeCredentials } from "@/generated/soulfire/common_pb";
import { splitAccountCredentialPayloads } from "@/lib/account-credential-payloads.ts";

const COOKIES = AccountTypeCredentials.MICROSOFT_JAVA_COOKIES;

function cookieJar(value: string) {
  return [
    "# Netscape HTTP Cookie File",
    "# https://curl.se/docs/http-cookies.html",
    "# This file was generated by libcurl! Edit at your own risk.",
    "",
    `.login.live.com\tTRUE\t/\tTRUE\t0\t__Host-MSAAUTHP\t${value}`,
    `#HttpOnly_.live.com\tTRUE\t/\tTRUE\t0\tMSPAuth\t${value}`,
  ].join("\n");
}

function cookieEditorExport(value: string) {
  return `[\n  {"name": "__Host-MSAAUTHP", "value": "${value}"}\n]`;
}

describe("splitAccountCredentialPayloads", () => {
  test("keeps one payload per line for line based formats", () => {
    expect(
      splitAccountCredentialPayloads(
        " alice \n\n bob\r\n",
        AccountTypeCredentials.OFFLINE,
      ),
    ).toEqual(["alice", "bob"]);
  });

  test("drops the Netscape comment header but keeps HttpOnly cookies", () => {
    const payloads = splitAccountCredentialPayloads(cookieJar("a"), COOKIES);
    expect(payloads).toHaveLength(1);
    expect(payloads[0]).toContain("#HttpOnly_.live.com");
    expect(payloads[0]).not.toContain("Netscape HTTP Cookie File");
  });

  test("splits cookie jars from several files joined by a blank line", () => {
    const text = [cookieJar("a"), cookieJar("b")].join("\n\n");
    const payloads = splitAccountCredentialPayloads(text, COOKIES);
    expect(payloads).toHaveLength(2);
    expect(payloads[0]).toContain("__Host-MSAAUTHP\ta");
    expect(payloads[1]).toContain("__Host-MSAAUTHP\tb");
  });

  test("splits Cookie-Editor exports from several files", () => {
    const payloads = splitAccountCredentialPayloads(
      [cookieEditorExport("a"), cookieEditorExport("b")].join("\n\n"),
      COOKIES,
    );
    expect(payloads).toEqual([
      cookieEditorExport("a"),
      cookieEditorExport("b"),
    ]);
  });

  test("treats lines with only spaces as blank lines between cookie jars", () => {
    const text = `${cookieJar("a")}\n  \n${cookieJar("b")}`;
    expect(splitAccountCredentialPayloads(text, COOKIES)).toHaveLength(2);
  });
});
